//! Shared acceptance helpers for #27 slice 1.
//!
//! * Media is **synthetic**: solid-colour clips generated by ffmpeg into a temp dir per test.
//! * Scene detection is **real** (visual-analysis through `analyze`).
//! * Speech and visible-text producers here are **fakes** written by the acceptance
//!   agent. They stand in for caller-supplied producers; no ASR or OCR model runs.

#![allow(dead_code)]

use std::cell::Cell;
use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

use media_intelligence_analysis::{
    AnalysisProfile, AnalysisRequest, AssetId, ContentHash, EvidenceAnalysis, MediaIdentity,
    Modality, ProducerError, ProducerIdentity, ProducerInput, ProducerReceipt, SceneConfig,
    SpeechProducer, SpeechRun, VisibleTextProducer, VisibleTextRun,
};
use media_intelligence_core::{
    CoverageStatus, EvidenceContent, OcrObservation, OcrTrack, RelationKind, TranscriptSegment,
};
use sha2::{Digest, Sha256};
use tempfile::TempDir;

/// A generated clip on disk. The directory is removed on drop.
pub struct Clip {
    pub dir: TempDir,
    pub path: PathBuf,
    pub content_hash: ContentHash,
}

fn ffmpeg_binary() -> Option<&'static str> {
    // FfmpegVideoSource invokes `ffmpeg`/`ffprobe` from PATH, so both must run.
    let runs = |program: &str| {
        Command::new(program)
            .arg("-version")
            .output()
            .map(|output| output.status.success())
            .unwrap_or(false)
    };
    if !runs("ffmpeg") || !runs("ffprobe") {
        return None;
    }
    if Path::new("/usr/bin/ffmpeg").is_file() {
        Some("/usr/bin/ffmpeg")
    } else {
        Some("ffmpeg")
    }
}

/// Generates solid-colour segments `(colour, seconds)` at 320x240, 25 fps, H.264.
/// Returns `None` (after printing an explicit skip message) when ffmpeg/ffprobe are absent.
pub fn generate_clip(test: &str, segments: &[(&str, u32)]) -> Option<Clip> {
    let Some(ffmpeg) = ffmpeg_binary() else {
        eprintln!(
            "SKIPPED {test}: ffmpeg/ffprobe not found on PATH; this test needs them to \
             generate synthetic media and to run the real visual-analysis scene producer"
        );
        return None;
    };
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("clip.mp4");
    let mut command = Command::new(ffmpeg);
    command.args(["-hide_banner", "-loglevel", "error", "-y"]);
    for (colour, seconds) in segments {
        command.args([
            "-f",
            "lavfi",
            "-i",
            &format!("color=c={colour}:s=320x240:r=25:d={seconds}"),
        ]);
    }
    let inputs: String = (0..segments.len()).map(|i| format!("[{i}:v]")).collect();
    command.args([
        "-filter_complex",
        &format!("{inputs}concat=n={}:v=1:a=0[v]", segments.len()),
        "-map",
        "[v]",
        "-c:v",
        "libx264",
        "-threads",
        "1",
        "-pix_fmt",
        "yuv420p",
        "-bitexact",
        "-fflags",
        "+bitexact",
    ]);
    command.arg(&path);
    let status = command.status().unwrap();
    assert!(status.success(), "ffmpeg failed to generate the clip");
    let content_hash = file_hash(&path);
    Some(Clip {
        dir,
        path,
        content_hash,
    })
}

/// Red 5 s, green 7 s, blue 4 s: three scenes [0,5), [5,12), [12,16).
pub fn three_scene_clip(test: &str) -> Option<Clip> {
    generate_clip(test, &[("red", 5), ("green", 7), ("blue", 4)])
}

pub fn file_hash(path: &Path) -> ContentHash {
    ContentHash::from_bytes(fs::read(path).unwrap())
}

pub fn sha256_hex(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

pub fn media_for(clip_path: &Path, content_hash: ContentHash) -> MediaIdentity {
    let _ = clip_path;
    MediaIdentity {
        asset_id: AssetId::new("acceptance:issue-27-synthetic-clip").unwrap(),
        content_hash,
        duration_seconds: Some(16.0),
    }
}

pub fn request(clip: &Clip, profile: AnalysisProfile) -> AnalysisRequest {
    AnalysisRequest {
        media: media_for(&clip.path, clip.content_hash.clone()),
        media_path: clip.path.clone(),
        profile,
    }
}

pub fn scenes_only() -> AnalysisProfile {
    AnalysisProfile {
        speech: false,
        visible_text: false,
        scenes: Some(SceneConfig::default()),
    }
}

pub fn everything() -> AnalysisProfile {
    AnalysisProfile {
        speech: true,
        visible_text: true,
        scenes: Some(SceneConfig::default()),
    }
}

/// `sha256:<hex>`, the receipt input hash convention for media with this content hash.
pub fn expected_input_hash(content_hash: &ContentHash) -> String {
    format!("sha256:{}", content_hash.as_str())
}

// ---------------------------------------------------------------------------------------
// Fake producers (acceptance-authored; not model output).
// ---------------------------------------------------------------------------------------

#[derive(Debug, Clone)]
pub enum Behaviour {
    /// Return the run.
    Succeed,
    /// Return a completed run with no items.
    SucceedEmpty,
    /// Return `ProducerError::Failed` with this reason.
    Fail(String),
    /// Cancel the shared token, then return `ProducerError::Cancelled`.
    CancelThenStop,
    /// Return a run whose receipt names a different input hash.
    WrongInputHash,
    /// Overwrite the media file with other bytes, then return the run.
    RewriteMediaThenSucceed,
}

pub fn identity(producer: &str, config_hash: &str) -> ProducerIdentity {
    ProducerIdentity {
        producer: producer.to_string(),
        producer_version: "acceptance-fake-1".to_string(),
        model: format!("{producer}-model"),
        model_version: "fake-model-1".to_string(),
        config_hash: config_hash.to_string(),
    }
}

fn receipt(modality: Modality, identity: &ProducerIdentity, input_hash: &str) -> ProducerReceipt {
    ProducerReceipt {
        modality,
        producer: identity.producer.clone(),
        producer_version: identity.producer_version.clone(),
        model: identity.model.clone(),
        model_version: identity.model_version.clone(),
        config_hash: identity.config_hash.clone(),
        input_hash: input_hash.to_string(),
        run_id: None,
        config: None,
    }
}

fn rewrite(path: &Path) {
    fs::write(path, b"replaced while the analysis was running").unwrap();
}

/// Speech aligned with the three-scene clip; segment 1 crosses the cut at 5 s.
pub fn fake_segments() -> Vec<TranscriptSegment> {
    let segment = |index, start, end, text: &str| TranscriptSegment {
        index,
        start_seconds: start,
        end_seconds: end,
        text: text.to_string(),
        language: Some("en".to_string()),
        speaker: None,
        confidence: Some(0.9),
    };
    vec![
        segment(0, 1.0, 4.0, "this is the red part"),
        segment(1, 4.5, 5.5, "crossing the first cut"),
        segment(2, 6.0, 10.0, "now everything is green"),
        segment(3, 13.0, 15.0, "and finally blue"),
    ]
}

pub struct FakeSpeech {
    pub identity: ProducerIdentity,
    pub behaviour: Behaviour,
    pub calls: Cell<usize>,
}

impl FakeSpeech {
    pub fn new(behaviour: Behaviour) -> Self {
        Self::with_config(behaviour, "sha256:fake-speech-config-a")
    }

    pub fn with_config(behaviour: Behaviour, config_hash: &str) -> Self {
        Self {
            identity: identity("fake-speech", config_hash),
            behaviour,
            calls: Cell::new(0),
        }
    }
}

impl SpeechProducer for FakeSpeech {
    fn identity(&self) -> ProducerIdentity {
        self.identity.clone()
    }

    fn run(&self, input: &ProducerInput<'_>) -> Result<SpeechRun, ProducerError> {
        self.calls.set(self.calls.get() + 1);
        let mut input_hash = input.input_hash.to_string();
        let mut segments = fake_segments();
        match &self.behaviour {
            Behaviour::Succeed => {}
            Behaviour::SucceedEmpty => segments.clear(),
            Behaviour::Fail(reason) => {
                return Err(ProducerError::Failed {
                    reason: reason.clone(),
                })
            }
            Behaviour::CancelThenStop => {
                input.cancellation.cancel();
                return Err(ProducerError::Cancelled);
            }
            Behaviour::WrongInputHash => input_hash = format!("sha256:{}", "0".repeat(64)),
            Behaviour::RewriteMediaThenSucceed => rewrite(input.media_path),
        }
        Ok(SpeechRun {
            receipt: receipt(Modality::Speech, &self.identity, &input_hash),
            segments,
        })
    }
}

/// OCR aligned with the three-scene clip: one untracked frame per red/blue scene, and two
/// green frames grouped by the producer into one track.
pub fn fake_ocr(receipt: ProducerReceipt, empty: bool) -> VisibleTextRun {
    let observation = |id: &str, t: f64, text: &str| OcrObservation {
        id: id.to_string(),
        text: text.to_string(),
        timestamp_seconds: t,
        frame_index: Some((t * 25.0) as u64),
        language: Some("en".to_string()),
        region: None,
        confidence: Some(0.8),
    };
    if empty {
        return VisibleTextRun {
            receipt,
            observations: vec![],
            tracks: vec![],
        };
    }
    VisibleTextRun {
        receipt,
        observations: vec![
            observation("o1", 2.0, "RED SLIDE"),
            observation("o2", 8.0, "GREEN SLIDE"),
            observation("o3", 9.0, "GREEN SLIDE"),
            observation("o4", 14.0, "BLUE SLIDE"),
        ],
        tracks: vec![OcrTrack {
            id: "t1".to_string(),
            text: "GREEN SLIDE".to_string(),
            role: Some("slide_title".to_string()),
            observation_ids: vec!["o2".to_string(), "o3".to_string()],
        }],
    }
}

pub struct FakeOcr {
    pub identity: ProducerIdentity,
    pub behaviour: Behaviour,
    pub calls: Cell<usize>,
}

impl FakeOcr {
    pub fn new(behaviour: Behaviour) -> Self {
        Self::with_config(behaviour, "sha256:fake-ocr-config-a")
    }

    pub fn with_config(behaviour: Behaviour, config_hash: &str) -> Self {
        Self {
            identity: identity("fake-ocr", config_hash),
            behaviour,
            calls: Cell::new(0),
        }
    }
}

impl VisibleTextProducer for FakeOcr {
    fn identity(&self) -> ProducerIdentity {
        self.identity.clone()
    }

    fn run(&self, input: &ProducerInput<'_>) -> Result<VisibleTextRun, ProducerError> {
        self.calls.set(self.calls.get() + 1);
        let mut input_hash = input.input_hash.to_string();
        let mut empty = false;
        match &self.behaviour {
            Behaviour::Succeed => {}
            Behaviour::SucceedEmpty => empty = true,
            Behaviour::Fail(reason) => {
                return Err(ProducerError::Failed {
                    reason: reason.clone(),
                })
            }
            Behaviour::CancelThenStop => {
                input.cancellation.cancel();
                return Err(ProducerError::Cancelled);
            }
            Behaviour::WrongInputHash => input_hash = format!("sha256:{}", "0".repeat(64)),
            Behaviour::RewriteMediaThenSucceed => rewrite(input.media_path),
        }
        Ok(fake_ocr(
            receipt(Modality::VisibleText, &self.identity, &input_hash),
            empty,
        ))
    }
}

// ---------------------------------------------------------------------------------------
// Inspection helpers.
// ---------------------------------------------------------------------------------------

pub fn coverage(analysis: &EvidenceAnalysis, modality: Modality) -> &CoverageStatus {
    &analysis
        .coverage
        .iter()
        .find(|entry| entry.modality == modality)
        .expect("one coverage entry per modality")
        .status
}

pub fn count(analysis: &EvidenceAnalysis, modality: Modality) -> usize {
    analysis
        .evidence
        .iter()
        .filter(|item| item.modality == modality)
        .count()
}

/// Human label per evidence id: `scene#<index>`, `speech#<index>`, `ocr:<track or obs id>`.
pub fn labels(analysis: &EvidenceAnalysis) -> BTreeMap<String, String> {
    analysis
        .evidence
        .iter()
        .map(|item| {
            let label = match &item.content {
                EvidenceContent::Scene(scene) => format!("scene#{}", scene.scene_index),
                EvidenceContent::Speech(speech) => format!("speech#{}", speech.segment_index),
                EvidenceContent::VisibleText(text) => match &text.track_id {
                    Some(track) => format!("ocr:{track}"),
                    None => format!("ocr:{}", text.observations[0].observation_id),
                },
            };
            (item.id.clone(), label)
        })
        .collect()
}

pub fn labelled_relations(analysis: &EvidenceAnalysis) -> BTreeSet<(RelationKind, String, String)> {
    let labels = labels(analysis);
    analysis
        .relations
        .iter()
        .map(|relation| {
            (
                relation.kind,
                labels[&relation.subject].clone(),
                labels[&relation.object].clone(),
            )
        })
        .collect()
}

pub fn evidence_ids(analysis: &EvidenceAnalysis, modality: Modality) -> Vec<String> {
    analysis
        .evidence
        .iter()
        .filter(|item| item.modality == modality)
        .map(|item| item.id.clone())
        .collect()
}

/// Rebuilds the scene run from composed scene evidence (receipt + scene payload), so a
/// test can recompose it independently through the core.
pub fn scene_run_from_evidence(analysis: &EvidenceAnalysis) -> media_intelligence_core::SceneRun {
    let mut receipt = None;
    let scenes = analysis
        .evidence
        .iter()
        .filter_map(|item| match &item.content {
            EvidenceContent::Scene(scene) => {
                receipt = Some(item.receipt.clone());
                Some(media_intelligence_core::SceneInterval {
                    id: scene.scene_id.clone(),
                    index: scene.scene_index,
                    start_seconds: item.start_seconds,
                    end_seconds: item.end_seconds,
                    start_frame: scene.start_frame,
                    end_frame: scene.end_frame,
                })
            }
            _ => None,
        })
        .collect();
    media_intelligence_core::SceneRun {
        receipt: receipt.expect("at least one scene item"),
        scenes,
    }
}
